// ── API Key (server-to-server) ──
// Many APIs accept key in Authorization header or custom header
const OPENAI_KEY = process.env.OPENAI_API_KEY;  // never hardcode!

const res = await fetch('https://api.openai.com/v1/models', {
    headers: {
        'Authorization': `Bearer ${OPENAI_KEY}`,  // OpenAI uses Bearer
    },
});

// Some APIs use a custom header:
const weather = await fetch('https://api.openweathermap.org/data/2.5/weather?q=London', {
    headers: { 'x-api-key': process.env.WEATHER_KEY },
});

// Some APIs accept it as a query param (avoid — appears in logs):
// fetch(`...?appid=${key}`)  ← use header instead when available

// ── Login → Bearer Token flow ──
async function login(email, password) {
    const res = await fetch('/api/auth/login', {
        method:  'POST',
        headers: { 'Content-Type': 'application/json' },
        body:    JSON.stringify({ email, password }),
    });
    if (!res.ok) throw new Error('Invalid credentials');
    const { token, refreshToken } = await res.json();

    // Store token — in memory for security, localStorage for persistence
    sessionStorage.setItem('token', token);
    return token;
}

// ── Authenticated request helper ──
function authFetch(url, options = {}) {
    const token = sessionStorage.getItem('token');
    return fetch(url, {
        ...options,
        headers: {
            ...options.headers,
            'Authorization': token ? `Bearer ${token}` : undefined,
            'Content-Type': 'application/json',
        },
    });
}

// Usage:
const profile = await authFetch('/api/users/me').then(r => r.json());

// ── Decode JWT payload (client-side preview only) ──
function decodeToken(jwt) {
    const [, payload] = jwt.split('.');
    return JSON.parse(atob(payload.replace(/-/g,'+').replace(/_/g,'/')));
}
